(()=>{
 const identity=document.querySelector('.nav .identity');identity.innerHTML='<span class="nav-wordmark">AIyuyu</span>';identity.setAttribute('aria-label','AIyuyu，返回首页');
 document.querySelector('.hero-copy').innerHTML=`<p class="hero-greeting">Hi <img src="assets/hello-wave.png" alt="" width="26" height="26">, I'm JIANGXIPING</p><h1>把想法，做成<br>看得见的作品。</h1><div class="hero-person"><h2>蒋希萍</h2><p class="role">视觉设计师 · AIGC创作者</p></div><p class="scope">品牌视觉 · 数字页面 · 原创IP · AI影像</p><a class="button" href="#index">查看作品目录 <span aria-hidden="true">↓</span></a><div class="contact-inline"><a href="tel:13520973005">手机：135 2097 3005</a><br><a href="mailto:13520973005@163.com">邮箱：13520973005@163.com</a></div>`;

 // One accessible, local-only lightbox for the requested artwork groups.
 const modal=document.createElement('dialog');modal.className='image-preview';modal.id='image-preview';modal.setAttribute('aria-labelledby','preview-title');
 modal.innerHTML=`<div class="preview-layout"><header class="preview-head"><h2 id="preview-title">作品预览</h2><div class="preview-actions"><button type="button" class="preview-mode">适宽阅读</button><button type="button" class="preview-close" autofocus>关闭 ×</button></div></header><div class="preview-stage" tabindex="0" aria-label="放大图片阅读区"><img alt=""></div><footer class="preview-foot"><span class="preview-count"></span><span>长图可上下滚动 · Esc 关闭</span><div class="preview-navigation"><button type="button" class="preview-prev" aria-label="上一张作品">← 上一张</button><button type="button" class="preview-next" aria-label="下一张作品">下一张 →</button></div></footer></div>`;document.body.append(modal);
 const stage=modal.querySelector('.preview-stage'),full=stage.querySelector('img'),mode=modal.querySelector('.preview-mode');let group=[],selected=0,restoreFocus=null,previousOverflow='',generation=0;
 function setWidth(width){stage.classList.toggle('read-width',width);mode.textContent=width?'完整预览':'适宽阅读';mode.setAttribute('aria-pressed',String(width))}
 function show(index){selected=(index+group.length)%group.length;const image=group[selected];const token=++generation;modal.querySelector('#preview-title').textContent=image.closest('figure')?.querySelector('figcaption')?.textContent||image.alt||'作品预览';full.src=image.currentSrc||image.src;full.alt=image.alt;modal.querySelector('.preview-count').textContent=`${selected+1} / ${group.length}`;const ready=()=>{if(token!==generation)return;setWidth(full.naturalHeight/full.naturalWidth>1.65);stage.scrollTo(0,0)};if(full.complete)ready();else full.onload=ready;}
 function open(image,images,trigger){restoreFocus=trigger;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';group=images;show(images.indexOf(image));modal.showModal()}
 const selectors=['#visual .posters img','#visual .more-posters img','#digital .split-product img','#digital .product-story img','#ip .ip-grid img','#ip .ip-end img'];
 selectors.forEach(selector=>{const images=[...document.querySelectorAll(selector)];images.forEach(image=>{const button=document.createElement('button');button.type='button';button.className='image-open';button.setAttribute('aria-label',`放大预览：${image.alt}`);button.setAttribute('aria-haspopup','dialog');image.before(button);button.append(image);const hint=document.createElement('span');hint.className='preview-hint';hint.textContent='点击放大 ⤢';hint.setAttribute('aria-hidden','true');button.append(hint);button.addEventListener('click',()=>open(image,images,button))})});
 mode.addEventListener('click',()=>{setWidth(!stage.classList.contains('read-width'));stage.scrollTo(0,0)});modal.querySelector('.preview-close').addEventListener('click',()=>modal.close());modal.querySelector('.preview-prev').addEventListener('click',()=>show(selected-1));modal.querySelector('.preview-next').addEventListener('click',()=>show(selected+1));
 modal.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();show(selected+(e.key==='ArrowRight'?1:-1))}});modal.addEventListener('close',()=>{document.body.style.overflow=previousOverflow;restoreFocus?.focus({preventScroll:true})});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});

 // Match the full-page preview height to its neighbouring content instead of leaving a tall empty column.
 const split=document.querySelector('.split-product'),left=split.firstElementChild,right=split.lastElementChild;
 const label=document.createElement('div');label.className='scroll-preview-label';label.textContent='完整网页 · 向下滚动预览 / 点击放大';right.prepend(label);
 const size=()=>{if(innerWidth>800)right.style.height=`${Math.ceil(left.getBoundingClientRect().height)}px`;else right.style.height='420px'};new ResizeObserver(size).observe(left);addEventListener('resize',size,{passive:true});size();

 // Encode only the two existing video destinations. Never send private assets to a QR service.
 document.querySelectorAll('.film-card').forEach((card,i)=>{const link=card.querySelector('a');const row=document.createElement('div');row.className='film-watch';link.before(row);row.append(link);const qr=document.createElement('figure');qr.className='watch-qr';const img=document.createElement('img');img.src=i===0?'assets/qr-ad.png':'assets/qr-cyber.png';img.alt=`扫一扫，观看${card.querySelector('h3').textContent}`;img.width=112;img.height=112;const caption=document.createElement('figcaption');caption.textContent='扫一扫，观看';qr.append(img,caption);row.append(qr)});
 const brandHint=document.querySelector('.brand-open-hint');const hintCopy=brandHint.lastChild;
 const updateHint=()=>{hintCopy.textContent=innerWidth<=800?' 点击上方图片，在本站展开完整作品':' 点击左侧图片，在本站展开完整作品'};updateHint();addEventListener('resize',updateHint,{passive:true});
})();
